-- =============================================================================
-- Étape 4b (partie 1) : rapprochement par empreinte, cartes KR et TC AUTO
-- Projet : Pkmn-collection — 2026-10-11
--
-- Source : prototype d'empreinte (espèce, PV, retraite, attaques, illustrateur,
-- jeu, rareté), appliqué set par set. Seules les cartes SANS aucun rattachement
-- sont touchées : les rattachements de l'étape 4a ne bougent pas.
--
-- Pour chaque carte rapprochée :
--   1. une ligne card_entity_matches (méthode 'empreinte', statut 'auto') ;
--   2. cards.card_entity_id pointe vers la famille japonaise ;
--   3. la famille individuelle créée en 4a pour cette carte est supprimée.
--
-- DRY-RUN PAR DÉFAUT : la dernière ligne est « rollback ». Pour appliquer,
-- remplace-la par « commit ».
-- =============================================================================

